-- CAB-0003: scoped editorial import. Apply after the portrait assets are deployed.

begin;

do $$ begin
 if (select count(*) from public.entities where slug in ('amanah','dap') and type='party') <> 2 then raise exception 'CAB-0003: missing party parent'; end if;
 if exists(select 1 from public.entities where slug in ('mohamad-sabu','nga-kor-ming') and (type <> 'politician' or owner_id is not null)) then raise exception 'CAB-0003: profile type or ownership conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('kota raja','teluk intan') and slug not in ('mohamad-sabu','nga-kor-ming')) then raise exception 'CAB-0003: constituency identity collision requires review'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'CAB-0003:%' and (m.source_type <> 'editorial' or e.slug not in ('mohamad-sabu','nga-kor-ming') or m.import_key not like 'CAB-0003:' || e.slug || ':%')) then raise exception 'CAB-0003: milestone identity conflict'; end if;
end $$;

insert into public.entities (type, parent_id, slug, name, bloc, position, constituency, state, description, website, photo_path, photo_source_url, photo_credit, profile_checked_at, profile_sources)
select 'politician', parent.id, 'mohamad-sabu', 'Mohamad Sabu', 'government', 'Minister of Agriculture and Food Security; President of AMANAH', 'Kota Raja', 'Selangor', 'Mohamad Sabu is Minister of Agriculture and Food Security and represents Kota Raja in Selangor. He is President of Parti Amanah Negara (AMANAH), a component of Pakatan Harapan.', 'https://www.kpkm.gov.my/', '/portraits/mohamad-sabu.webp', 'https://www.parlimen.gov.my/images/webuser/ahli/2022/P111.png', 'Parliament of Malaysia', '2026-11-08', '[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Kota Raja", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4150"}, {"label": "BERNAMA · AMANAH leadership (16 Oct 2026)", "url": "https://www.bernama.com/radio/news.php?id=2621528"}]'::jsonb from public.entities parent where parent.slug='amanah'
on conflict (slug) do update set parent_id=excluded.parent_id, name=excluded.name, bloc=excluded.bloc, position=excluded.position, constituency=excluded.constituency, state=excluded.state, description=excluded.description, website=excluded.website, photo_path=excluded.photo_path, photo_source_url=excluded.photo_source_url, photo_credit=excluded.photo_credit, profile_checked_at=excluded.profile_checked_at, profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null;

insert into public.entities (type, parent_id, slug, name, bloc, position, constituency, state, description, website, photo_path, photo_source_url, photo_credit, profile_checked_at, profile_sources)
select 'politician', parent.id, 'nga-kor-ming', 'Nga Kor Ming', 'government', 'Minister of Housing and Local Government; Deputy Chairman of DAP', 'Teluk Intan', 'Perak', 'Nga Kor Ming is Minister of Housing and Local Government and Member of Parliament for Teluk Intan, Perak. He is Deputy Chairman of DAP, a component of Pakatan Harapan.', 'https://www.kpkt.gov.my/', '/portraits/nga-kor-ming.webp', 'https://www.parlimen.gov.my/images/webuser/ahli/2022/P076.png', 'Parliament of Malaysia', '2026-11-08', '[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Teluk Intan", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4115"}, {"label": "DAP · current leadership", "url": "https://dapmalaysia.org/en/our-leaders/"}]'::jsonb from public.entities parent where parent.slug='dap'
on conflict (slug) do update set parent_id=excluded.parent_id, name=excluded.name, bloc=excluded.bloc, position=excluded.position, constituency=excluded.constituency, state=excluded.state, description=excluded.description, website=excluded.website, photo_path=excluded.photo_path, photo_source_url=excluded.photo_source_url, photo_credit=excluded.photo_credit, profile_checked_at=excluded.profile_checked_at, profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null;

do $$ begin if (select count(*) from public.entities where slug in ('mohamad-sabu','nga-kor-ming') and type='politician' and owner_id is null) <> 2 then raise exception 'CAB-0003: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id, import_key, title, category, status, progress, target_date, promise_date, promise_url, evidence_date, evidence_url, description, progress_note, progress_checked_at, source_type, is_sample)
select e.id, 'CAB-0003:mohamad-sabu:rice-ssr-80-2030', 'Raise rice self-sufficiency to 80% by 2030', 'Economy', 'in_progress', null, '2030-12-31', '2023-11-10', 'https://www.kpkm.gov.my/images/06-informasi/keratan-akhbar/2023/november/10-min.pdf', '2026-10-02', 'https://www.bernama.com/en/general/news.php?id=2614495', 'Mohamad Sabu set an 80% rice self-sufficiency target for 2030 in remarks carried by the ministry’s November 2023 media archive.', 'KPKM’s October 2026 statement, reported by BERNAMA after a meeting chaired by Mohamad, gives a 2025 rice self-sufficiency ratio of 54.3% and describes measures to protect padi land. This dated food-supply ratio is not a completion score. The target remains in progress, not achieved.', '2026-11-08', 'editorial', false from public.entities e where e.slug='mohamad-sabu'
on conflict (import_key) do update set title=excluded.title, category=excluded.category, status=excluded.status, progress=excluded.progress, target_date=excluded.target_date, promise_date=excluded.promise_date, promise_url=excluded.promise_url, evidence_date=excluded.evidence_date, evidence_url=excluded.evidence_url, description=excluded.description, progress_note=excluded.progress_note, progress_checked_at=excluded.progress_checked_at, source_type=excluded.source_type, is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial';

insert into public.milestones (entity_id, import_key, title, category, status, progress, target_date, promise_date, promise_url, evidence_date, evidence_url, description, progress_note, progress_checked_at, source_type, is_sample)
select e.id, 'CAB-0003:mohamad-sabu:beef-ssr-50-2030', 'Reach 50% beef and buffalo-meat self-sufficiency by 2030', 'Economy', 'in_progress', null, '2030-12-31', '2025-12-11', 'https://www.bernama.com/en/general/news.php?id=2501519', '2026-09-29', 'https://www.dosm.gov.my/uploads/release-content/file_20260929091755.pdf', 'Mohamad Sabu reaffirmed a 50% beef/buffalo-meat self-sufficiency target for 2030 and described support for livestock investment and production.', 'The minister’s December 2025 statement reported roughly 17% beef self-sufficiency for the preceding year. DOSM’s September 2026 release reports 82.6% beef import dependency for 2025. Import dependency is a different indicator; it is not converted into self-sufficiency or a completion percentage. The numerical completion field remains blank.', '2026-11-08', 'editorial', false from public.entities e where e.slug='mohamad-sabu'
on conflict (import_key) do update set title=excluded.title, category=excluded.category, status=excluded.status, progress=excluded.progress, target_date=excluded.target_date, promise_date=excluded.promise_date, promise_url=excluded.promise_url, evidence_date=excluded.evidence_date, evidence_url=excluded.evidence_url, description=excluded.description, progress_note=excluded.progress_note, progress_checked_at=excluded.progress_checked_at, source_type=excluded.source_type, is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial';

insert into public.milestones (entity_id, import_key, title, category, status, progress, target_date, promise_date, promise_url, evidence_date, evidence_url, description, progress_note, progress_checked_at, source_type, is_sample)
select e.id, 'CAB-0003:nga-kor-ming:affordable-homes-2035', 'Provide one million affordable homes by 2035', 'Housing', null, null, '2035-12-31', '2026-08-10', 'https://www.kpkt.gov.my/kpkt/resources/user_1/media_akhbar/2026/SM_10082026_KPKT_LUNCUR_DASAR_PERUMAHAN_NEGARA_2026-2035.pdf', null, null, 'At the launch of the National Housing Policy 2026–2035, Nga announced a target of one million affordable homes by 2035.', 'The ministry release establishes the target and the policy launch. It does not establish delivery of one million homes. A target-specific delivery total was not verified in this batch, so outcome status and completion percentage remain unknown.', '2026-11-08', 'editorial', false from public.entities e where e.slug='nga-kor-ming'
on conflict (import_key) do update set title=excluded.title, category=excluded.category, status=excluded.status, progress=excluded.progress, target_date=excluded.target_date, promise_date=excluded.promise_date, promise_url=excluded.promise_url, evidence_date=excluded.evidence_date, evidence_url=excluded.evidence_url, description=excluded.description, progress_note=excluded.progress_note, progress_checked_at=excluded.progress_checked_at, source_type=excluded.source_type, is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial';

insert into public.milestones (entity_id, import_key, title, category, status, progress, target_date, promise_date, promise_url, evidence_date, evidence_url, description, progress_note, progress_checked_at, source_type, is_sample)
select e.id, 'CAB-0003:nga-kor-ming:rmr-10000-annually', 'Increase Rumah Mesra Rakyat delivery to 10,000 homes a year', 'Housing', null, null, null, '2025-09-18', 'https://www.bernama.com/en/general/news.php?id=2468901', null, null, 'Nga said the annual Rumah Mesra Rakyat target would be raised to 10,000 homes through collaboration with government, private-sector and community partners.', 'The announcement does not establish a particular calendar-year deadline or a completed annual delivery total. Those fields remain blank rather than turning an annual target into a dated achievement.', '2026-11-08', 'editorial', false from public.entities e where e.slug='nga-kor-ming'
on conflict (import_key) do update set title=excluded.title, category=excluded.category, status=excluded.status, progress=excluded.progress, target_date=excluded.target_date, promise_date=excluded.promise_date, promise_url=excluded.promise_url, evidence_date=excluded.evidence_date, evidence_url=excluded.evidence_url, description=excluded.description, progress_note=excluded.progress_note, progress_checked_at=excluded.progress_checked_at, source_type=excluded.source_type, is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial';

commit;
